(function () {
  // One place builds every filter STRING, for the same reason flow 11's PREP
  // does: a filter written as a literal object in an http node's query value is
  // JSON.parsed by the flows MCP and reaches the wire as a Go map rendering.
  //
  // Two index rules govern every condition below and both fail SILENTLY:
  //  - a keyword field matches the STORED case, so ACTIVE/ISSUED are upper and
  //    pending/unpaid/scheduled are lower, exactly as the writer wrote them.
  //    (Only ANALYSED text fields want lowercase; there are none here.)
  //  - there is no negation. "not paid" is an OR over unpaid|overdue, and a
  //    payment state added later drops out of this report without saying so.
  var now = new Date();
  var iso = function (d) { return d.toISOString().replace(/\.\d{3}Z$/, 'Z'); };
  var plusDays = function (n) { return iso(new Date(now.getTime() + n * 86400000)); };
  var f = function (o) { return JSON.stringify(o); };
  var nowIso = iso(now);

  return {
    now: nowIso,
    renewal_window_end: plusDays(Number(renewalWindowDays) || 100),
    // 1. the timer was never scheduled, or was silently lost.
    filter_timers: f({ conditions: [
      { field: 'policy_status', keyword: 'ACTIVE' },
      { operator: 'OR', conditions: [
        { field: 'timers_scheduled', keyword: 'pending' },
        { field: 'timers_scheduled', keyword: 'failed' } ] } ] }),
    // 2. the void deadline passed and the notice was never sent. The stamp is
    //    read positively (voidance_notice_state = pending) because the absence
    //    of voidance_notice_sent_at is not a query.
    filter_void: f({ conditions: [
      { field: 'policy_status', keyword: 'ACTIVE' },
      { field: 'void_due_date', date_end: nowIso },
      { field: 'voidance_notice_state', keyword: 'pending' } ] }),
    // 3. an invoice past its due date that is still not paid.
    filter_invoices: f({ conditions: [
      { operator: 'OR', conditions: [
        { field: 'payment_status', keyword: 'unpaid' },
        { field: 'payment_status', keyword: 'overdue' } ] },
      { field: 'due_date', date_end: nowIso } ] }),
    // 4. an issued quote past its validity that the quote-expiry timer never
    //    lapsed.
    filter_quotes: f({ conditions: [
      { field: 'decision_status', keyword: 'ISSUED' },
      { field: 'quote_validity_expiry', date_end: nowIso } ] }),
    // 5. a policy still ACTIVE after its own expiration date.
    filter_expired: f({ conditions: [
      { field: 'policy_status', keyword: 'ACTIVE' },
      { field: 'expiration_date', date_end: nowIso } ] })
  };
})()

(function () {
  var esc = function (s) {
    return String(s === undefined || s === null ? '' : s)
      .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
  };

  // The index can return one record TWICE across an update (a pending and a
  // scheduled row for one id) and total_hits counts both, so every count here
  // is taken AFTER de-duplicating by record id. total_hits is reported beside
  // it precisely so a divergence is visible rather than averaged away.
  var norm = function (resp) {
    var body = (resp && resp.data) ? resp.data : {};
    var rows = Array.isArray(body.results) ? body.results : [];
    var seen = {}, out = [];
    for (var i = 0; i < rows.length; i++) {
      var id = rows[i] && rows[i].id;
      if (!id || seen[id]) continue;
      seen[id] = 1; out.push(rows[i]);
    }
    return { rows: out, unique: out.length, index_total_hits: body.total_hits, page_size: rows.length };
  };

  var d = function (v) { var t = Date.parse(v); return isNaN(t) ? null : t; };
  var days = function (from, to) { return Math.floor((to - from) / 86400000); };
  var nowMs = Date.parse(now);

  var P = norm(timers), V = norm(voids), I = norm(invoices),
      Q = norm(quotes), X = norm(expired);

  // Tasks are aged in code, not in the index: the index has no negation and the
  // task list is not a records query. awaiting_broker ages on a longer clock
  // than intake work (contract artefact 4).
  var taskBody = (tasks && tasks.data) ? tasks.data : {};
  var taskRows = Array.isArray(taskBody.results) ? taskBody.results : [];
  var seenTask = {}, agedTasks = [];
  for (var j = 0; j < taskRows.length; j++) {
    var t = taskRows[j]; if (!t || !t.id || seenTask[t.id]) continue; seenTask[t.id] = 1;
    var created = d(t.created_at); if (created === null) continue;
    var age = days(created, nowMs);
    var limit = t.status === 'awaiting_broker' ? Number(awaitingBrokerDays) : Number(openDays);
    if (age >= limit) {
      agedTasks.push({ id: t.id, status: t.status, age_days: age, threshold: limit, title: t.title || '' });
    }
  }

  var sections = [
    { key: 'timers_never_scheduled', label: 'ACTIVE policies whose timers are pending or failed',
      rows: P.rows.map(function (r) { return { id: r.id, ref: (r.data || {}).policy_number, detail: 'timers_scheduled=' + (r.data || {}).timers_scheduled }; }),
      hits: P.index_total_hits, unique: P.unique },
    { key: 'void_notice_unsent', label: 'ACTIVE policies past void_due_date with the notice still pending',
      rows: V.rows.map(function (r) { return { id: r.id, ref: (r.data || {}).policy_number, detail: 'void_due_date=' + (r.data || {}).void_due_date }; }),
      hits: V.index_total_hits, unique: V.unique },
    { key: 'invoices_overdue', label: 'Invoices past due_date and not paid',
      rows: I.rows.map(function (r) { return { id: r.id, ref: (r.data || {}).invoice_number, detail: 'due ' + (r.data || {}).due_date + ', ' + (r.data || {}).payment_status + ', paid ' + (r.data || {}).amount_paid + ' of ' + (r.data || {}).amount_due }; }),
      hits: I.index_total_hits, unique: I.unique },
    { key: 'issued_quotes_past_validity', label: 'ISSUED decisions past quote_validity_expiry that never lapsed',
      rows: Q.rows.map(function (r) { return { id: r.id, ref: (r.data || {}).quote_id, detail: 'valid until ' + (r.data || {}).quote_validity_expiry }; }),
      hits: Q.index_total_hits, unique: Q.unique },
    { key: 'policies_active_past_expiry', label: 'Policies still ACTIVE after their expiration_date',
      rows: X.rows.map(function (r) { return { id: r.id, ref: (r.data || {}).policy_number, detail: 'expired ' + (r.data || {}).expiration_date }; }),
      hits: X.index_total_hits, unique: X.unique },
    { key: 'tasks_ageing', label: 'Open underwriting work past its ageing threshold',
      rows: agedTasks.map(function (t) { return { id: t.id, ref: t.status, detail: t.age_days + ' days old (threshold ' + t.threshold + '): ' + t.title }; }),
      hits: agedTasks.length, unique: agedTasks.length }
  ];

  var total = 0, html = '', summary = [];
  for (var s = 0; s < sections.length; s++) {
    var sec = sections[s];
    total += sec.rows.length;
    summary.push(sec.key + '=' + sec.rows.length);
    html += '<h3>' + esc(sec.label) + ' — ' + sec.rows.length + '</h3>';
    if (!sec.rows.length) { html += '<p>None.</p>'; continue; }
    html += '<ul>';
    for (var k = 0; k < sec.rows.length; k++) {
      html += '<li><code>' + esc(sec.rows[k].id) + '</code> ' + esc(sec.rows[k].ref) + ' — ' + esc(sec.rows[k].detail) + '</li>';
    }
    html += '</ul>';
    if (sec.hits !== undefined && sec.hits !== null && sec.hits !== sec.unique) {
      html += '<p><em>index total_hits ' + esc(sec.hits) + ' differs from ' + sec.unique +
              ' unique record ids — the index returned a record more than once.</em></p>';
    }
  }

  var body =
    '<p>Weekly lifecycle reconciliation for ' + esc(now) + '. This is a BACKSTOP, not the mechanism: ' +
    'the lifecycle is driven by per-entity timers and record events. Anything listed here is a case ' +
    'where a timer was never scheduled, was silently lost, or fired against a state nothing then acted on.</p>' +
    html +
    '<p>Scanned: policy_config, invoice_config, decision_config and the ANTIPODEAN task board. ' +
    'Every filter is a positive match — the index has no negation, so a status added later drops out of ' +
    'this report without saying so.</p>';

  return {
    now: now,
    exception_count: total,
    has_exceptions: total > 0,
    summary: summary.join(' '),
    sections: sections,
    email_subject: 'Antipodean lifecycle reconciliation — ' + total + ' exception' + (total === 1 ? '' : 's') + ' — ' + now.slice(0, 10),
    email_body_html: body,
    idempotency_key: 'lifecycle-reconcile-' + now.slice(0, 13)
  };
})()
